25	// Connected components by label propagation with pointer jumping.
26	//
27	// Every vertex starts as its own component label (IDs[i] = i) and each round
28	// propagates the smallest label seen so far along the edges (writeMin).  The
29	// labels therefore form a forest: IDs[i] is always the id of some vertex in
30	// i's component and IDs[x] <= x holds for every x.  In addition to the plain
31	// propagation of Components.C, each round finishes with a pointer-jumping
32	// (shortcutting) step, IDs[i] = IDs[IDs[i]], applied to the vertices whose
33	// label just changed.  Shortcutting collapses long chains in that forest, so a
34	// vertex hands its neighbours a much smaller label in the next round and the
35	// computation converges in fewer rounds.
36	//
37	// A vertex is kept in the frontier only while its label keeps changing, so the
38	// loop ends exactly when no label moved, which (on a symmetric graph) means
39	// every vertex holds the minimum id of its component.  The final labelling is
40	// therefore identical to the one computed by Components.C, not merely an
41	// equivalent partition.
42	#include "ligra.h"
43	
44	// Update function: propagate the smaller label to d with writeMin.  prevIDs
45	// holds the label d had at the start of the round, so "the label was still
46	// prevIDs[d] before this write" identifies the first decrease of IDs[d] in
47	// this round and d is placed in the output frontier exactly once.
48	struct CC_F {
49	  uintE* IDs, *prevIDs;
50	  CC_F(uintE* _IDs, uintE* _prevIDs) :
51	    IDs(_IDs), prevIDs(_prevIDs) {}
52	  inline bool update(uintE s, uintE d) { //Update
53	    uintE origID = IDs[d];
54	    if(IDs[s] < origID) {
55	      IDs[d] = IDs[s];
56	      if(origID == prevIDs[d]) return 1;
57	    }
58	    return 0;
59	  }
60	  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
61	    uintE origID = IDs[d];
62	    return (writeMin(&IDs[d],IDs[s]) && origID == prevIDs[d]);
63	  }
64	  //cond function is always true: a label may improve any number of times
65	  inline bool cond (uintE d) { return cond_true(d); }
66	};
67	
68	//vertex map function used to sync prevIDs with IDs at the start of a round
69	struct CC_Vertex_F {
70	  uintE* IDs, *prevIDs;
71	  CC_Vertex_F(uintE* _IDs, uintE* _prevIDs) :
72	    IDs(_IDs), prevIDs(_prevIDs) {}
73	  inline bool operator () (uintE i) {
74	    prevIDs[i] = IDs[i];
75	    return 1;
76	  }
77	};
