79	// Vertex filter function performing the pointer jumping: IDs[i] is replaced by
80	// IDs[IDs[i]], following the chain up to the root of i's label tree.  Because
81	// IDs[x] <= x for every x the chain strictly decreases, so it cannot cycle and
82	// the walk terminates; every label on it belongs to i's component, hence the
83	// jump never leaves the component and never increases a label.  Only IDs[i]
84	// itself is written -- a vertex outside the frontier must not have its label
85	// changed here, or the change would never be propagated to its neighbours.
86	// The vertex stays in the frontier only while its label keeps changing.
87	struct CC_Shortcut {
88	  uintE* IDs, *prevIDs;
89	  CC_Shortcut(uintE* _IDs, uintE* _prevIDs) :
90	    IDs(_IDs), prevIDs(_prevIDs) {}
91	  inline bool operator () (uintE i) {
92	    uintE l = IDs[i];
93	    while(l != IDs[l]) l = IDs[l]; //walk to the root of the label tree
94	    writeMin(&IDs[i],l);           //IDs[i] = IDs[IDs[i]] = ... = l
95	    return (prevIDs[i] != IDs[i]); //active only if the label changed
96	  }
97	};
