101	  long n = GA.n;
102	  uintE* IDs = newA(uintE,n), *prevIDs = newA(uintE,n);
103	  {parallel_for(long i=0;i<n;i++) IDs[i] = i;} //initialize unique IDs
104	  {parallel_for(long i=0;i<n;i++) prevIDs[i] = i;}
105	
106	  bool* frontier = newA(bool,n);
107	  {parallel_for(long i=0;i<n;i++) frontier[i] = 1;}
108	  vertexSubset Frontier(n,n,frontier); //initial frontier contains all vertices
109	
110	  long rounds = 0;
111	  while(!Frontier.isEmpty()){ //iterate until IDs converge
112	    rounds++;
113	    //remember the label each active vertex starts the round with
114	    vertexMap(Frontier,CC_Vertex_F(IDs,prevIDs));
115	    //propagate the smallest label along the edges
116	    vertexSubset output = edgeMap(GA, Frontier, CC_F(IDs,prevIDs));
117	    //pointer jump on the vertices that just changed, keeping the ones that
118	    //really did change as the next frontier
119	    output.toDense(); //materialize the dense form here so that del() frees it
120	    vertexSubset next = vertexFilter(output, CC_Shortcut(IDs,prevIDs));
121	    Frontier.del(); output.del();
122	    Frontier = next;
123	  }
124	  Frontier.del();
125	
126	  // Number of components = number of distinct labels.  At convergence every
127	  // vertex holds the smallest id of its component, so this also equals the
128	  // number of vertices i with IDs[i] == i, which is how Components.C counts.
129	  long* label_used = newA(long,n);
130	  {parallel_for(long i=0;i<n;i++) label_used[i] = 0;}
131	  {parallel_for(long i=0;i<n;i++) label_used[IDs[i]] = 1;}
132	  long components = sequence::plusReduce(label_used,n);
133	
134	  cout << "Components-Shortcut rounds: " << rounds << endl;
135	  cout << "Components: " << components << endl;
136	
137	  free(label_used); free(IDs); free(prevIDs);
138	}
